    'compression-garments': { name: 'Vetements de compression', summary: 'Hub de support pour documenter quand la compression est utilisee et si elle change symptomes ou fonction.', definition: 'Vetements de compression est une page Zebra pour documenter des strategies de soutien dans la meme chronologie que symptomes et fonction quotidienne.' },
    'medication-tracking': { name: 'Suivi des medicaments', summary: 'Hub de workflow pour garder medicaments, changements de dose et timing connectes a l historique des symptomes et de la fonction.', definition: 'Suivi des medicaments est une page Zebra pour noter ce qui a change, quand, et quels symptomes ou changements fonctionnels etaient proches de cette fenetre.' },
    flare: { name: 'Poussee', summary: 'Periode d aggravation ou pic de symptomes utile a suivre comme schema plutot que de compter sur la memoire.', definition: 'La page Poussee de Zebra se concentre sur ce qui a change, combien de temps cela a dure, ce qui se passait autour et l impact sur la fonction ou les questions de suivi.' },
    'baseline-symptoms': { name: 'Symptomes de reference', summary: 'Page de workflow pour noter ce qui est normal pour vous avant qu une poussee, un changement de medicament ou un rendez-vous rende les details plus difficiles a rappeler.', definition: 'Symptomes de reference separe dans Zebra votre schema habituel de ce qui a change, empire ou commence a arriver plus souvent avant un rendez-vous.', practicalUse: { title: 'Quoi noter en premier', body: 'Une reference est plus utile quand elle est simple et precise. Elle n a pas besoin d expliquer pourquoi les symptomes arrivent; elle doit seulement capturer a quoi ressemble une semaine normale avant un changement.', items: ['Symptomes habituellement presents meme un jour ordinaire', 'Ce qui compte comme pire que d habitude pour douleur, vertiges, fatigue, brouillard mental ou symptomes cardiaques', 'Ce que vous pouvez faire d habitude, comme rester debout, marcher, cuisiner, travailler ou sortir', 'Contexte habituel de medicaments, sel, eau, sommeil, chaleur ou activite'] }, appointmentUse: { title: 'Comment cela aide avant un rendez-vous', body: 'La valeur en consultation est le contraste. Au lieu d expliquer tout le mois de memoire, vous pouvez montrer ce qui etait typique, ce qui a change et quand cela a commence.', items: ['L utiliser avant un nouveau medicament ou changement de dose', 'L utiliser apres une poussee pour comparer la phase plus difficile', 'L utiliser avant un rendez-vous si les symptomes bougent depuis plusieurs semaines'] } },
    trigger: { name: 'Declencheur', summary: 'Page de workflow pour noter chaleur, activite, stress, repas, mauvais sommeil ou autre contexte autour des symptomes.', definition: 'Declencheur est une page Zebra pour garder le contexte attache aux symptomes sans suraffirmer une causalite.' },
    'symptom-severity': { name: 'Severite du symptome', summary: 'Page de workflow pour noter l intensite ou le caractere perturbant sans transformer le suivi en devoir.', definition: 'Severite du symptome est une page Zebra pour documenter si quelque chose etait leger, modere, severe, nouveau ou assez perturbant pour compter plus tard.' },
    'quality-of-life': { name: 'Qualite de vie', summary: 'Page centree sur la fonction : comment les symptomes changent travail, courses, sommeil, concentration, vie sociale ou routines.', definition: 'Qualite de vie est une page Zebra sur l impact pratique des symptomes dans la vie quotidienne, pas seulement leurs noms.' },
    'activities-of-daily-living': { name: 'Activites de la vie quotidienne', summary: 'Page de fonction pour suivre ce que les symptomes changent dans les routines, mouvements, concentration et autonomie quotidienne.', definition: 'Activites de la vie quotidienne est une page Zebra sur les taches de routine que les symptomes peuvent perturber, surtout quand cet impact s oublie facilement.' },
